package net.minecraft.util;public class Vec3{public double xCoord,yCoord,zCoord;public static Vec3 createVectorHelper(double x,double y,double z){var v=new Vec3();v.xCoord=x;v.yCoord=y;v.zCoord=z;return v;}public Vec3 normalize(){double length=Math.sqrt(xCoord*xCoord+yCoord*yCoord+zCoord*zCoord);return createVectorHelper(xCoord/length,yCoord/length,zCoord/length);}}
